def find_first_occurrence(arr: list, target) -> int:
    """
    Return the index of the first occurrence of target in a sorted array.
    Returns -1 if the target is not present.
    """
    left, right = 0, len(arr)

    while left < right:
        mid = (left + right) // 2

        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid

    if left < len(arr) and arr[left] == target:
        return left
    return -1


if __name__ == "__main__":
    assert find_first_occurrence([2, 5, 5, 5, 6, 6, 8, 9, 9, 9], 5) == 1
