def circular_shift(x, shift):
    negative = x < 0
    digits = str(abs(x))
    n = len(digits)

    if shift < 0:
        shift %= n

    if shift > n:
        result = digits[::-1]
    else:
        result = digits[-shift:] + digits[:-shift]

    return "-" + result if negative else result
