from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG = -10**18

        dp0 = [NEG] * n
        dp1 = [NEG] * n
        dp2 = [NEG] * n

        for i in range(m):
            left0 = left1 = left2 = NEG

            for j in range(n):
                if i == 0 and j == 0:
                    prev0, prev1, prev2 = 0, NEG, NEG
                else:
                    prev0 = dp0[j] if dp0[j] > left0 else left0
                    prev1 = dp1[j] if dp1[j] > left1 else left1
                    prev2 = dp2[j] if dp2[j] > left2 else left2

                val = coins[i][j]

                if val >= 0:
                    cur0 = prev0 + val if prev0 != NEG else NEG
                    cur1 = prev1 + val if prev1 != NEG else NEG
                    cur2 = prev2 + val if prev2 != NEG else NEG
                else:
                    cur0 = cur1 = cur2 = NEG

                    if prev0 != NEG:
                        cand = prev0 + val
                        if cand > cur0:
                            cur0 = cand
                        if prev0 > cur1:
                            cur1 = prev0

                    if prev1 != NEG:
                        cand = prev1 + val
                        if cand > cur1:
                            cur1 = cand
                        if prev1 > cur2:
                            cur2 = prev1

                    if prev2 != NEG:
                        cand = prev2 + val
                        if cand > cur2:
                            cur2 = cand

                dp0[j] = cur0
                dp1[j] = cur1
                dp2[j] = cur2

                left0, left1, left2 = cur0, cur1, cur2

        return max(dp0[n - 1], dp1[n - 1], dp2[n - 1])
