class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def get_substrings(x: str):
            subs = [""]
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    subs.append(x[i:j])
            return subs

        left_substrings = [(sub, len(sub)) for sub in get_substrings(s)]
        right_substrings = [(sub, len(sub)) for sub in get_substrings(t)]

        ans = 0
        max_possible = len(s) + len(t)

        for left, left_len in left_substrings:
            for right, right_len in right_substrings:
                total_len = left_len + right_len
                if total_len <= ans:
                    continue

                candidate = left + right
                if candidate == candidate[::-1]:
                    ans = total_len
                    if ans == max_possible:
                        return ans

        return ans
