from typing import List

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        if not grid or not grid[0]:
            return []

        rows = len(grid)
        cols = len(grid[0])
        result = []
        should_visit = True

        for r in range(rows):
            if r % 2 == 0:
                cols_range = range(cols)
            else:
                cols_range = range(cols - 1, -1, -1)

            for c in cols_range:
                if should_visit:
                    result.append(grid[r][c])
                should_visit = not should_visit

        return result
