from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)

        size = 1
        while size < n:
            size <<= 1

        seg = [-1] * (2 * size)

        for i, cap in enumerate(baskets):
            seg[size + i] = cap

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[i << 1], seg[(i << 1) | 1])

        def first_available_ge(x: int) -> int:
            if seg[1] < x:
                return -1

            node = 1
            while node < size:
                left = node << 1
                if seg[left] >= x:
                    node = left
                else:
                    node = left | 1

            idx = node - size
            return idx if idx < n else -1

        unplaced = 0

        for fruit in fruits:
            pos = first_available_ge(fruit)

            if pos == -1:
                unplaced += 1
            else:
                node = size + pos
                seg[node] = -1
                node >>= 1

                while node:
                    seg[node] = max(seg[node << 1], seg[(node << 1) | 1])
                    node >>= 1

        return unplaced
