from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        distinct_values = set(nums)
        max_gain = 0

        for value in distinct_values:
            if value == k:
                continue

            current = 0
            best = 0

            for num in nums:
                if num == value:
                    current += 1
                elif num == k:
                    current -= 1

                if current > best:
                    best = current
                if current < 0:
                    current = 0

            if best > max_gain:
                max_gain = best

        return total_k + max_gain
